def conform(path):
    """Run the published vectors against this reader. Other implementations: same file, same verdicts."""
    v = json.load(open(path))
    root = tempfile.mkdtemp()
    fails = 0
    try:
        H = {}
        for n, k in v["keys"].items():
            H[n] = os.path.join(root, n)
            os.makedirs(H[n], mode=0o700)
            import_key(k["secret"], H[n])                       # own secret key
        for n in H:                                             # everyone else's public key
            for m, k2 in v["keys"].items():
                if m != n:
                    import_key(gpg(["--export", k2["fpr"]], home=H[m]).stdout, H[n])
        parts = []
        for case in v["cases"]:
            a = v["keys"][case["author"]]["fpr"]
            try:
                env = v["envelopes"][case["envelope"]]
                h, body = open_post(env, a, case["thread"], H[case["reader"]])
                if case["expect"].startswith("part:"):
                    parts.append((h, body, a))
                    got = "part: " + h["part"]
                else:
                    got = "accept: " + body.decode()
            except Reject as e:
                got = "reject: " + str(e)
            want = case["expect"]
            good = got.startswith(want) if want.startswith("accept") or want.startswith("part") else \
                (got.startswith("reject") and want.split(": ", 1)[1].lower() in got.lower())
            fails += not good
            print(("PASS " if good else "FAIL ") + case["name"] + ("" if good else f"  (want {want!r}, got {got!r})"))
    finally:
        shutil.rmtree(root, ignore_errors=True)
    return fails == 0


if __name__ == "__main__":
    a = sys.argv[1:]
    if not a:
        sys.exit(__doc__)
    if a[0] == "selftest":
        sys.exit(0 if selftest() else 1)
    elif a[0] == "conform" and len(a) == 2:
        sys.exit(0 if conform(a[1]) else 1)
    elif a[0] == "keygen":
        cmd_keygen(a[1])
    elif a[0] == "register":
        cmd_register()
    elif a[0] == "send" and len(a) >= 5:
        cmd_send(a[1], a[2], a[3], a[4:])
    elif a[0] == "read" and len(a) >= 2:
        cmd_read(a[1], a[2] if len(a) > 2 else None)
    else:
