def registry_keys(home=None, posts=None, verbose=False):
    """account -> primary fpr. Only strict courier-key-binding/1 posts count; an account's latest valid one wins.
    Everything else in the registry thread (chat, quoted keys, v0.1 registrations) is ignored."""
    keys, arm = {}, {}
    for p in posts if posts is not None else thread_posts(REGISTRY):
        try:
            fpr, _, armored = parse_binding(p)
        except Reject as e:
            if verbose and "BEGIN PGP" in p["body"]:
                print(f"# registry seq {p['seq']} {p['author']}: ignored ({e})")
            continue
        keys[p["author"]], arm[p["author"]] = fpr, armored
    for a in keys:
        import_key(arm[a], home)
    return keys


# ------------------------------------------------------------------ format
def header_block(fields):
    return "".join(f"{k}: {v}\n" for k, v in fields)


def parse(pt):
    """Plaintext -> (version, headers, body bytes). Strict: no folding, no duplicates, LF only."""
    head, sep, body = pt.partition(b"\n\n")
    if not sep or len(head) > HDR_MAX or b"\r" in head:
        raise Reject("header block missing, too large or has CR")
    lines = head.decode("utf-8").split("\n")
    m = re.fullmatch(r"COURIER/(\d+)\.(\d+)", lines[0])
    if not m or len(lines) - 1 > HDR_LINES:
        raise Reject("bad version line or too many headers")
    h = {}
    for ln in lines[1:]:
        if len(ln) > LINE_MAX or ln[:1] in (" ", "\t") or ": " not in ln:
            raise Reject("malformed header line")
        k, v = ln.split(": ", 1)
        k = k.lower()
        if k in h:
            raise Reject(f"duplicate header {k}")
        h[k] = v
    for k in REQUIRED:
        if k not in h:
            raise Reject(f"missing {k}")
    if "pad" in h:
        if not h["pad"].isdigit() or int(h["pad"]) > len(body):
            raise Reject("bad Pad")
        body = body[:len(body) - int(h["pad"])]
    return (int(m.group(1)), int(m.group(2))), h, body


def members_hash(fprs):
    return hashlib.sha256("\n".join(sorted(fprs)).encode()).hexdigest()


def seal(text, to, thread, mode, group=None, ack=None, home=None):
    """Returns the list of post bodies (one per part)."""
    if mode not in ("pair", "room", "square"):
        raise Reject("mode must be pair|room|square")
    me = my_fpr(home)
    to = sorted(set(to))
    raw = text.replace("\r\n", "\n").encode("utf-8")
    fixed = [("To", ", ".join(to)), ("Thread", thread), ("Msg-Id", str(uuid.uuid4()))]
    if group:
        fixed.append(("Group", f"{group[0]}; epoch={group[1]}; members={members_hash(group[2])}"))
    if ack:
        fixed.append(("Ack", ", ".join(ack)))
    overhead = len("COURIER/2.0\n") + len(header_block(fixed)) + len("Part: 16/16\nPad: 4096\n\n")
    room = PT_BUCKETS[-1] - overhead
    chunks = [raw[i:i + room] for i in range(0, len(raw), room)] or [b""]
    if len(chunks) > MAX_PARTS:
        raise Reject("message too long")
    n = len(chunks)
    need = overhead + max(len(c) for c in chunks)
    bucket = next(b for b in PT_BUCKETS if b >= need)   # one bucket for all parts: the last part leaks nothing
    rcpt = list(dict.fromkeys(to + [me]))
    if mode == "square":
        size = next((b for b in RCPT_BUCKETS if b >= len(rcpt)), None)
        if size is None:
            raise Reject("too many recipients")
        rcpt += dummy_pool(size - len(rcpt), home)
        random.shuffle(rcpt)
    elif len(rcpt) > RCPT_BUCKETS[-1]:
        raise Reject("too many recipients")
    posts = []
    for k, c in enumerate(chunks, 1):
        hdr = ("COURIER/2.0\n" + header_block(fixed + [("Part", f"{k}/{n}")])).encode()
        pad = 0
        for _ in range(3):  # Pad value length feeds back into the size
            pad = bucket - len(hdr) - len(f"Pad: {pad}\n\n") - len(c)
        pt = hdr + f"Pad: {pad}\n\n".encode() + c + b"." * pad
        assert len(pt) == bucket, (len(pt), bucket)
        args = ["--compress-algo", "none", "--local-user", me, "--sign", "--encrypt"]
        if mode == "square":
            args.append("--throw-keyids")
        for r in rcpt:
            args += ["-r", r]
        pgp = gpg(args, pt, home).stdout
        b64 = base64.b64encode(pgp).decode()
        post = f"COURIER/2.0 spec={SPEC_ID}\n" + "\n".join(b64[i:i + 76] for i in range(0, len(b64), 76))
        if len(post.encode()) > POST_MAX:
            raise Reject(f"envelope {len(post)} B over post limit: fewer recipients or shorter text")
        posts.append(post)
    return posts


def open_post(body, author_fpr, thread, home=None):
    """Verify one envelope. author_fpr = registry key of the post's author. Returns (headers, body bytes)."""
    if len(body.encode()) > POST_MAX:
        raise Reject("oversize envelope")
    first, _, rest = body.partition("\n")
    m = re.fullmatch(r"COURIER/(\d+)\.(\d+)(?: spec=\S+)?", first.strip())
    if not m:
        raise Reject("not a COURIER/2 envelope")
    outer = (int(m.group(1)), int(m.group(2)))
    if outer[0] != VERSION[0]:
        raise Reject(f"unsupported major version {outer[0]}")
    try:
        pgp = base64.b64decode("".join(rest.split()), validate=True)
    except Exception:
        raise Reject("bad base64")
    p = gpg(["--max-output", str(PT_BUCKETS[-1] + 64), "--decrypt"], pgp, home, check=False)
    st = p.stderr.decode(errors="replace")
    if "DECRYPTION_OKAY" not in st:
        raise Reject("not for us")
    if "compressed packet" in gpg(["--list-packets"], pgp, home, check=False).stdout.decode():
        raise Reject("compressed payload (MUST NOT)")
    sig = re.search(r"\[GNUPG:\] VALIDSIG (?:\S+ ){9}([0-9A-F]{40})", st)
    if not sig or re.search(r"\[GNUPG:\] (BADSIG|ERRSIG|EXPKEYSIG|REVKEYSIG)", st):
        raise Reject("no valid signature")
    if sig.group(1) != author_fpr:
        raise Reject("signer is not the post author")
    ver, h, text = parse(p.stdout)
    if ver != outer:
        raise Reject("inner/outer version mismatch")
    me = my_fpr(home)
    if me not in [x.strip() for x in h["to"].split(",")] and me != author_fpr:  # own sent copy is fine
        raise Reject("we are not in To: forwarded envelope")
    if h["thread"] != thread:
        raise Reject("Thread does not match the thread it was posted in: transplant")
    if not re.fullmatch(r"\d+/\d+", h["part"]):
        raise Reject("bad Part")
    k, n = map(int, h["part"].split("/"))
    if not 1 <= k <= n <= MAX_PARTS:
        raise Reject("Part out of range")
    return h, text


